const chatInput = String($json.chatInput || '');
const sessionId = String($json.sessionId || 'local-chat');
const data = loadState();
const saved = data.sessions[sessionId] || {};
let orgId = saved.orgId || 'org_a';
let customerId = saved.customerId || 'a_nima';
const orgMatch = chatInput.match(/\borg:(\S+)/);
const customerMatch = chatInput.match(/\bcustomer:(\S+)/);
if (orgMatch) orgId = orgMatch[1];
