// Business rules for Himali Tea House and Lotus Wellness Studio.
// Tools call these functions. A system prompt cannot skip them.

const TIME_ZONE = "Asia/Kathmandu";
const OFFSET_MS = (5 * 60 + 45) * 60 * 1000;
const WEEKDAYS = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];

function createStore(seed) {
  const store = JSON.parse(JSON.stringify(seed));
  store.seq = 100;
  return store;
}

function chooseState(candidates, seed) {
  const ready = (candidates || []).filter((row) => row && row.store);
  ready.sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
  const best = ready[0];
  const store = best ? best.store : createStore(seed);
  const sessions = best && best.sessions ? best.sessions : {};
  if (typeof store.seq !== "number" || Number.isNaN(store.seq)) store.seq = 100;
  return { store, sessions, savedAt: best && best.savedAt ? best.savedAt : 0 };
}

function kathmanduParts(date) {
  const fmt = new Intl.DateTimeFormat("en-US", {
    timeZone: TIME_ZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    weekday: "short",
    hour: "2-digit",
    minute: "2-digit",
    hourCycle: "h23",
  });
  const bag = {};
  for (const part of fmt.formatToParts(date)) bag[part.type] = part.value;
  const weekday = WEEKDAYS.includes(bag.weekday) ? bag.weekday : bag.weekday.slice(0, 3);
  return {
    year: Number(bag.year),
    month: Number(bag.month),
    day: Number(bag.day),
    weekday,
    hour: Number(bag.hour),
    minute: Number(bag.minute),
    dateKey: bag.year + "-" + bag.month + "-" + bag.day,
  };
}

function kathmanduToUtc(year, month, day, hour, minute) {
  return new Date(Date.UTC(year, month - 1, day, hour, minute) - OFFSET_MS);
}

function resolvePhrase(phrase, now = new Date()) {
  const text = String(phrase || "").toLowerCase();
  if (!text.includes("tuesday") || !text.includes("afternoon")) {
    return { ok: false, code: "unparsed_phrase", message: "Say a clearer time, such as next Tuesday afternoon." };
  }
  const start = kathmanduParts(now);
  const today = WEEKDAYS.indexOf(start.weekday);
  let delta = (2 - today + 7) % 7;
  if (delta === 0) delta = 7;
  const todayAfternoon = kathmanduToUtc(start.year, start.month, start.day, 14, 0);
  const target = new Date(todayAfternoon.getTime() + delta * 24 * 60 * 60 * 1000);
  const parts = kathmanduParts(target);
  return {
    ok: true,
    timeZone: TIME_ZONE,
    start: target.toISOString(),
    local: parts.dateKey + " 14:00",
    weekday: parts.weekday,
    hour: parts.hour,
  };
}

function nextId(store, prefix) {
  if (typeof store.seq !== "number" || Number.isNaN(store.seq)) store.seq = 100;
  store.seq += 1;
  return prefix + String(store.seq);
}

function customerRow(store, orgId, customerId) {
  return store.customers.find((row) => row.id === customerId && row.orgId === orgId) || null;
}

function fail(code, message, extra) {
  return Object.assign({ ok: false, code, message }, extra || {});
}

function requireCustomer(store, orgId, customerId) {
  const customer = customerRow(store, orgId, customerId);
  if (!customer) return fail("wrong_org", "This customer is not in this shop.");
  return { ok: true, customer };
}

function productRow(store, orgId, sku) {
  return store.products.find((row) => row.orgId === orgId && row.sku === sku) || null;
}

function mergeLines(items) {
  if (!Array.isArray(items) || items.length === 0) return fail("items_required", "Add at least one product.");
  const map = new Map();
  for (const row of items) {
    const sku = String(row.sku || "").trim();
    const qty = Number(row.qty);
    if (!sku || !Number.isInteger(qty) || qty < 1) return fail("bad_item", "Each item needs a sku and a whole quantity of 1 or more.");
    map.set(sku, (map.get(sku) || 0) + qty);
  }
  return { ok: true, lines: Array.from(map, ([sku, qty]) => ({ sku, qty })) };
}

function alternativeFor(store, orgId, product, need) {
  const options = store.products.filter((row) => {
    return row.orgId === orgId && row.category === product.category && row.sku !== product.sku && row.stock >= need;
  });
  options.sort((a, b) => b.stock - a.stock || a.sku.localeCompare(b.sku));
  if (!options.length) return null;
  const pick = options[0];
  return { sku: pick.sku, name: pick.name, price: pick.price, stock: pick.stock, category: pick.category };
}

function heldQty(lines, sku) {
  return (lines || []).filter((row) => row.sku === sku).reduce((sum, row) => sum + row.qty, 0);
}

function priceLines(store, orgId, lines, heldLines) {
  const priced = [];
  const problems = [];
  for (const line of lines) {
    const item = productRow(store, orgId, line.sku);
    if (!item) {
      problems.push({ sku: line.sku, code: "unknown_sku", message: "That product is not in this shop." });
      continue;
    }
    const have = item.stock + heldQty(heldLines, line.sku);
    if (line.qty > have) {
      const alternative = alternativeFor(store, orgId, item, line.qty);
      problems.push({
        sku: line.sku,
        name: item.name,
        code: "insufficient_stock",
        have,
        need: line.qty,
        alternative,
        message: alternative
          ? "Only " + have + " left of " + item.name + ". You can try " + alternative.name + " instead."
          : "Only " + have + " left of " + item.name + ".",
      });
    }
    priced.push({
      sku: item.sku,
      name: item.name,
      qty: line.qty,
      unitPrice: item.price,
      lineTotal: item.price * line.qty,
    });
  }
  const total = priced.reduce((sum, row) => sum + row.lineTotal, 0);
  return { priced, problems, total };
}

function summaryOf(priced, address) {
  return {
    items: priced.priced,
    total: priced.total,
    payment: "cash_on_delivery",
    address: address || "",
  };
}

function reserve(store, orgId, lines) {
  for (const line of lines) productRow(store, orgId, line.sku).stock -= line.qty;
}

function release(store, orgId, lines) {
  for (const line of lines) {
    const item = productRow(store, orgId, line.sku);
    if (item) item.stock += line.qty;
  }
}

function ownOrder(store, orgId, customerId, orderId) {
  const order = store.orders.find((row) => row.id === orderId);
  if (!order) return fail("not_your_order", "That order is not in this shop.");
  if (order.orgId !== orgId || order.customerId !== customerId) {
    return fail("not_your_order", "That order is not yours.");
  }
  return { ok: true, order };
}

function pendingOnly(order, verb) {
  if (order.status === "pending") return { ok: true };
  return fail("not_pending", "This order is " + order.status + ". Only a pending order can be " + verb + ".", {
    status: order.status,
  });
}

const STOP_WORDS = new Set(["the", "and", "for", "how", "you", "your", "what", "with", "this", "that", "are", "can", "does", "from", "about"]);

function wordStem(word) {
  if (word.length > 5 && word.endsWith("age")) return word.slice(0, -3);
  if (word.length > 4 && word.endsWith("ing")) return word.slice(0, -3);
  if (word.length > 4 && word.endsWith("ed")) return word.slice(0, -2);
  if (word.length > 4 && word.endsWith("e")) return word.slice(0, -1);
  return word;
}

function searchKnowledge(store, input) {
  const orgId = input.orgId;
  const words = String(input.query || "")
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((word) => word.length > 2 && !STOP_WORDS.has(word))
    .map(wordStem);
  const rows = store.knowledge.filter((row) => row.orgId === orgId);
  const scored = [];
  for (const row of rows) {
    const section = (row.document + " " + row.section).toLowerCase();
    const text = row.text.toLowerCase();
    let score = 0;
    for (const word of words) {
      if (section.includes(word)) score += 5;
      else if (text.includes(word)) score += 1;
    }
    if (score > 0) scored.push({ row, score });
  }
  scored.sort((a, b) => b.score - a.score);
  return {
    ok: true,
    matches: scored.slice(0, 3).map((hit) => ({
      document: hit.row.document,
      section: hit.row.section,
      text: hit.row.text,
    })),
  };
}

function searchProducts(store, input) {
  const name = String(input.name || input.query || "").toLowerCase();
  const category = String(input.category || "").toLowerCase();
  const minPrice = input.minPrice == null ? null : Number(input.minPrice);
  const maxPrice = input.maxPrice == null ? null : Number(input.maxPrice);
  const rows = store.products.filter((row) => {
    if (row.orgId !== input.orgId) return false;
    if (name && !row.name.toLowerCase().includes(name) && !row.sku.toLowerCase().includes(name)) return false;
    if (category && row.category !== category) return false;
    if (minPrice != null && !Number.isNaN(minPrice) && row.price < minPrice) return false;
    if (maxPrice != null && !Number.isNaN(maxPrice) && row.price > maxPrice) return false;
    return true;
  });
  return {
    ok: true,
    products: rows.map((row) => ({
      sku: row.sku,
      name: row.name,
      category: row.category,
      price: row.price,
      stock: row.stock,
    })),
  };
}

function quoteOrder(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const norm = mergeLines(input.items);
  if (!norm.ok) return norm;
  const priced = priceLines(store, input.orgId, norm.lines, []);
  const summary = summaryOf(priced, input.address || gate.customer.address);
  if (priced.problems.length) {
    return fail("insufficient_stock", priced.problems[0].message, { problems: priced.problems, summary });
  }
  return { ok: true, summary, message: "This is a quote. Nothing is saved yet." };
}

function createOrder(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const norm = mergeLines(input.items);
  if (!norm.ok) return norm;
  const priced = priceLines(store, input.orgId, norm.lines, []);
  const address = input.address || gate.customer.address;
  const summary = summaryOf(priced, address);
  if (priced.problems.length) {
    return fail("insufficient_stock", priced.problems[0].message, { problems: priced.problems, summary });
  }
  if (input.confirm !== true) {
    return fail("confirm_required", "Show this summary and wait for a yes. Then call create_order with confirm true.", { summary });
  }
  const again = priceLines(store, input.orgId, norm.lines, []);
  if (again.problems.length) {
    return fail("insufficient_stock", again.problems[0].message, { problems: again.problems, summary: summaryOf(again, address) });
  }
  reserve(store, input.orgId, norm.lines);
  const at = new Date().toISOString();
  const order = {
    id: nextId(store, "ord_"),
    orgId: input.orgId,
    customerId: input.customerId,
    status: "pending",
    items: again.priced,
    total: again.total,
    address,
    payment: "cash_on_delivery",
    stockHeld: true,
    history: [{ status: "pending", at }],
    createdAt: at,
  };
  store.orders.push(order);
  return { ok: true, order, summary };
}

function updateOrder(store, input) {
  const owned = ownOrder(store, input.orgId, input.customerId, input.orderId);
  if (!owned.ok) return owned;
  const order = owned.order;
  const pending = pendingOnly(order, "changed");
  if (!pending.ok) return pending;
  const held = order.stockHeld ? order.items : [];
  const norm = input.items ? mergeLines(input.items) : { ok: true, lines: order.items.map((row) => ({ sku: row.sku, qty: row.qty })) };
  if (!norm.ok) return norm;
  const priced = priceLines(store, input.orgId, norm.lines, held);
  const address = input.address || order.address;
  const summary = summaryOf(priced, address);
  if (priced.problems.length) {
    return fail("insufficient_stock", priced.problems[0].message, { problems: priced.problems, summary, status: order.status });
  }
  if (input.confirm !== true) {
    return fail("confirm_required", "Show this summary and wait for a yes. Then call update_order with confirm true.", { summary, status: order.status });
  }
  if (order.stockHeld) release(store, input.orgId, order.items);
  reserve(store, input.orgId, norm.lines);
  order.items = priced.priced;
  order.total = priced.total;
  order.address = address;
  order.stockHeld = true;
  order.history.push({ status: "pending", at: new Date().toISOString(), note: "updated" });
  return { ok: true, order, summary };
}

function cancelOrder(store, input) {
  const owned = ownOrder(store, input.orgId, input.customerId, input.orderId);
  if (!owned.ok) return owned;
  const order = owned.order;
  const pending = pendingOnly(order, "cancelled");
  if (!pending.ok) return pending;
  const summary = {
    orderId: order.id,
    status: order.status,
    items: order.items,
    total: order.total,
  };
  if (input.confirm !== true) {
    return fail("confirm_required", "Wait for a yes before cancelling this pending order.", { summary, status: order.status });
  }
  if (order.stockHeld) release(store, input.orgId, order.items);
  order.stockHeld = false;
  order.status = "cancelled";
  order.history.push({ status: "cancelled", at: new Date().toISOString() });
  return { ok: true, order, summary };
}

function getOrderStatus(store, input) {
  const owned = ownOrder(store, input.orgId, input.customerId, input.orderId);
  if (!owned.ok) return owned;
  const order = owned.order;
  return {
    ok: true,
    orderId: order.id,
    status: order.status,
    items: order.items,
    total: order.total,
    history: order.history,
    address: order.address,
    payment: order.payment,
  };
}

function listMyOrders(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const rows = store.orders
    .filter((row) => row.orgId === input.orgId && row.customerId === input.customerId)
    .slice()
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
  return {
    ok: true,
    orders: rows.map((row) => ({
      id: row.id,
      status: row.status,
      items: row.items,
      total: row.total,
      createdAt: row.createdAt,
    })),
  };
}

function reorder(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const mine = store.orders
    .filter((row) => row.orgId === input.orgId && row.customerId === input.customerId && row.status !== "cancelled")
    .slice()
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
  if (!mine.length) return fail("no_previous_order", "There is no earlier order to repeat.");
  const last = mine[0];
  const lines = last.items.map((row) => ({ sku: row.sku, qty: row.qty }));
  const notes = [];
  for (const line of last.items) {
    const item = productRow(store, input.orgId, line.sku);
    if (!item) continue;
    if (item.price !== line.unitPrice) notes.push({ sku: line.sku, type: "price", from: line.unitPrice, to: item.price });
    if (item.stock < line.qty) notes.push({ sku: line.sku, type: "stock", need: line.qty, have: item.stock });
  }
  const priced = priceLines(store, input.orgId, lines, []);
  const summary = summaryOf(priced, last.address);
  summary.fromOrderId = last.id;
  summary.notes = notes;
  if (priced.problems.length) {
    return fail("insufficient_stock", priced.problems[0].message, { notes, problems: priced.problems, summary });
  }
  if (input.confirm !== true) {
    return fail("confirm_required", "Show the last order with current prices and wait for a yes.", { notes, summary });
  }
  const created = createOrder(store, {
    orgId: input.orgId,
    customerId: input.customerId,
    items: lines,
    address: last.address,
    confirm: true,
  });
  if (!created.ok) return Object.assign(created, { notes });
  return Object.assign(created, { notes, fromOrderId: last.id });
}

function advanceOrderStatus(store, input) {
  const order = store.orders.find((row) => row.id === input.orderId && row.orgId === input.orgId);
  if (!order) return fail("not_your_order", "That order is not in this shop.");
  const allowed = ["pending", "confirmed", "shipped", "delivered", "cancelled"];
  if (!allowed.includes(input.status)) return fail("bad_status", "That status is not used.");
  order.status = input.status;
  order.history.push({ status: input.status, at: new Date().toISOString(), note: "staff" });
  return { ok: true, orderId: order.id, status: order.status };
}

function namedRow(rows, orgId, key) {
  const name = String(key || "").trim().toLowerCase();
  const mine = rows.filter((row) => row.orgId === orgId);
  return mine.find((row) => row.id === key)
    || mine.find((row) => row.name.toLowerCase() === name)
    || mine.find((row) => name && row.name.toLowerCase().includes(name))
    || null;
}

function serviceRow(store, orgId, serviceId) {
  return namedRow(store.services, orgId, serviceId);
}

function practitionerRow(store, orgId, practitionerId) {
  return namedRow(store.practitioners, orgId, practitionerId);
}

function minutesOf(hhmm) {
  const bits = String(hhmm).split(":");
  return Number(bits[0]) * 60 + Number(bits[1]);
}

function slotFits(store, orgId, start, end) {
  const openAt = kathmanduParts(start);
  const closeAt = kathmanduParts(end);
  if (openAt.dateKey !== closeAt.dateKey) return fail("too_short", "That slot is not long enough for this service.");
  const holiday = store.holidays.find((row) => row.orgId === orgId && row.date === openAt.dateKey);
  if (holiday) return fail("holiday", "The studio is closed that day.", { holiday: holiday.name });
  const hours = store.hours.find((row) => row.orgId === orgId && row.weekday === openAt.weekday);
  if (!hours) return fail("outside_hours", "That time is outside opening hours.");
  const openMin = minutesOf(hours.open);
  const closeMin = minutesOf(hours.close);
  const startMin = openAt.hour * 60 + openAt.minute;
  const endMin = closeAt.hour * 60 + closeAt.minute;
  if (startMin < openMin || startMin >= closeMin) return fail("outside_hours", "That time is outside opening hours.");
  if (endMin > closeMin) return fail("too_short", "That slot is not long enough for this service.");
  return { ok: true, dateKey: openAt.dateKey };
}

function overlaps(aStart, aEnd, bStart, bEnd) {
  return aStart < bEnd && bStart < aEnd;
}

function conflicts(store, input) {
  const rows = store.bookings.filter((row) => row.status === "booked" && row.id !== input.ignoreBookingId && row.orgId === input.orgId);
  let practitionerBusy = false;
  let customerBusy = false;
  for (const row of rows) {
    if (!overlaps(input.startMs, input.endMs, Date.parse(row.start), Date.parse(row.end))) continue;
    if (row.practitionerId === input.practitionerId) practitionerBusy = true;
    if (row.customerId === input.customerId) customerBusy = true;
  }
  return { practitionerBusy, customerBusy };
}

function eachDateKey(fromKey, toKey) {
  const fromBits = fromKey.split("-").map(Number);
  const toBits = toKey.split("-").map(Number);
  let cursor = kathmanduToUtc(fromBits[0], fromBits[1], fromBits[2], 12, 0).getTime();
  const end = kathmanduToUtc(toBits[0], toBits[1], toBits[2], 12, 0).getTime();
  const keys = [];
  while (cursor <= end && keys.length < 31) {
    keys.push(kathmanduParts(new Date(cursor)).dateKey);
    cursor += 24 * 60 * 60 * 1000;
  }
  return keys;
}

function listServices(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  return {
    ok: true,
    services: store.services
      .filter((row) => row.orgId === input.orgId)
      .map((row) => ({ id: row.id, name: row.name, durationMin: row.durationMin, price: row.price })),
  };
}

function getOpeningHours(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  return {
    ok: true,
    timeZone: TIME_ZONE,
    hours: store.hours.filter((row) => row.orgId === input.orgId).map((row) => ({ weekday: row.weekday, open: row.open, close: row.close })),
    holidays: store.holidays.filter((row) => row.orgId === input.orgId).map((row) => ({ date: row.date, name: row.name })),
  };
}

function findAvailableSlots(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const service = serviceRow(store, input.orgId, input.serviceId || input.serviceName || input.service);
  if (!service) return fail("unknown_service", "That service is not at this studio.");
  const practitionerKey = input.practitionerId || input.practitionerName || input.practitioner;
  let people = store.practitioners.filter((row) => row.orgId === input.orgId);
  if (practitionerKey) {
    const person = practitionerRow(store, input.orgId, practitionerKey);
    if (!person) return fail("unknown_practitioner", "That practitioner is not at this studio.");
    people = [person];
  }
  let fromKey = input.from;
  let toKey = input.to;
  let minHour = null;
  let maxHour = null;
  if (input.phrase) {
    const when = resolvePhrase(input.phrase, input.now ? new Date(input.now) : new Date());
    if (!when.ok) return when;
    fromKey = when.local.slice(0, 10);
    toKey = fromKey;
    if (String(input.phrase).toLowerCase().includes("afternoon")) {
      minHour = 14;
      maxHour = 17;
    }
  }
  const today = kathmanduParts(input.now ? new Date(input.now) : new Date()).dateKey;
  if (!fromKey) fromKey = today;
  if (!toKey) toKey = fromKey;
  const slots = [];
  for (const dateKey of eachDateKey(fromKey, toKey)) {
    const bits = dateKey.split("-").map(Number);
    const noon = kathmanduParts(kathmanduToUtc(bits[0], bits[1], bits[2], 12, 0));
    const hours = store.hours.find((row) => row.orgId === input.orgId && row.weekday === noon.weekday);
    if (!hours) continue;
    if (store.holidays.some((row) => row.orgId === input.orgId && row.date === dateKey)) continue;
    const openMin = minutesOf(hours.open);
    const closeMin = minutesOf(hours.close);
    for (let minute = openMin; minute + service.durationMin <= closeMin; minute += 30) {
      const start = kathmanduToUtc(bits[0], bits[1], bits[2], Math.floor(minute / 60), minute % 60);
      const end = new Date(start.getTime() + service.durationMin * 60 * 1000);
      for (const person of people) {
        const hit = conflicts(store, {
          orgId: input.orgId,
          practitionerId: person.id,
          customerId: input.customerId,
          startMs: start.getTime(),
          endMs: end.getTime(),
        });
        if (hit.practitionerBusy || hit.customerBusy) continue;
        const local = kathmanduParts(start);
        if (minHour != null && (local.hour < minHour || local.hour >= maxHour)) continue;
        slots.push({
          start: start.toISOString(),
          end: end.toISOString(),
          local: local.dateKey + " " + String(local.hour).padStart(2, "0") + ":" + String(local.minute).padStart(2, "0"),
          serviceId: service.id,
          serviceName: service.name,
          durationMin: service.durationMin,
          price: service.price,
          practitionerId: person.id,
          practitionerName: person.name,
        });
        break;
      }
    }
  }
  return { ok: true, timeZone: TIME_ZONE, slots };
}

function bookingSummary(service, person, start, price) {
  const local = kathmanduParts(start);
  return {
    serviceId: service.id,
    service: service.name,
    practitionerId: person.id,
    practitioner: person.name,
    date: local.dateKey,
    time: String(local.hour).padStart(2, "0") + ":" + String(local.minute).padStart(2, "0"),
    timeZone: TIME_ZONE,
    price,
  };
}

function lockBooking(store, input) {
  const hit = conflicts(store, input);
  if (hit.practitionerBusy) return fail("slot_taken", "That time was just taken. Pick another slot.");
  if (hit.customerBusy) return fail("customer_busy", "You already have a booking at that time.");
  return { ok: true };
}

function createBooking(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const service = serviceRow(store, input.orgId, input.serviceId || input.serviceName || input.service);
  if (!service) return fail("unknown_service", "That service is not at this studio.");
  const person = practitionerRow(store, input.orgId, input.practitionerId || input.practitionerName || input.practitioner);
  if (!person) return fail("unknown_practitioner", "That practitioner is not at this studio.");
  let startValue = input.start;
  if (!startValue && input.phrase) {
    const when = resolvePhrase(input.phrase, input.now ? new Date(input.now) : new Date());
    if (!when.ok) return when;
    startValue = when.start;
  }
  const start = new Date(startValue);
  if (Number.isNaN(start.getTime())) return fail("bad_time", "Give a start time.");
  const end = new Date(start.getTime() + service.durationMin * 60 * 1000);
  const fit = slotFits(store, input.orgId, start, end);
  if (!fit.ok) return fit;
  const summary = bookingSummary(service, person, start, service.price);
  const lock = lockBooking(store, {
    orgId: input.orgId,
    practitionerId: person.id,
    customerId: input.customerId,
    startMs: start.getTime(),
    endMs: end.getTime(),
  });
  if (!lock.ok) {
    const nearest = nearestSlots(store, input, start);
    return Object.assign(lock, { summary, nearest });
  }
  if (input.confirm !== true) {
    return fail("confirm_required", "Show the service, practitioner, date, time, and price. Wait for a yes.", { summary });
  }
  const again = lockBooking(store, {
    orgId: input.orgId,
    practitionerId: person.id,
    customerId: input.customerId,
    startMs: start.getTime(),
    endMs: end.getTime(),
  });
  if (!again.ok) return Object.assign(again, { summary, nearest: nearestSlots(store, input, start) });
  const booking = {
    id: nextId(store, "book_"),
    orgId: input.orgId,
    customerId: input.customerId,
    serviceId: service.id,
    practitionerId: person.id,
    start: start.toISOString(),
    end: end.toISOString(),
    price: service.price,
    status: "booked",
  };
  store.bookings.push(booking);
  return { ok: true, booking, summary };
}

function nearestSlots(store, input, start) {
  const from = kathmanduParts(start).dateKey;
  const endProbe = new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000);
  const to = kathmanduParts(endProbe).dateKey;
  const found = findAvailableSlots(store, {
    orgId: input.orgId,
    customerId: input.customerId,
    serviceId: input.serviceId,
    practitionerId: input.practitionerId,
    from,
    to,
  });
  if (!found.ok) return [];
  return found.slots.filter((slot) => slot.start !== start.toISOString()).slice(0, 3);
}

function rescheduleBooking(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const booking = store.bookings.find((row) => row.id === input.bookingId);
  if (!booking || booking.orgId !== input.orgId || booking.customerId !== input.customerId || booking.status !== "booked") {
    return fail("not_your_booking", "That booking is not yours.");
  }
  const service = serviceRow(store, input.orgId, booking.serviceId);
  const practitionerId = input.practitionerId || booking.practitionerId;
  const person = practitionerRow(store, input.orgId, practitionerId);
  if (!service || !person) return fail("unknown_practitioner", "That practitioner is not at this studio.");
  const start = new Date(input.start);
  if (Number.isNaN(start.getTime())) return fail("bad_time", "Give a start time.");
  const end = new Date(start.getTime() + service.durationMin * 60 * 1000);
  const fit = slotFits(store, input.orgId, start, end);
  if (!fit.ok) return fit;
  const summary = bookingSummary(service, person, start, service.price);
  const lock = lockBooking(store, {
    orgId: input.orgId,
    practitionerId: person.id,
    customerId: input.customerId,
    startMs: start.getTime(),
    endMs: end.getTime(),
    ignoreBookingId: booking.id,
  });
  if (!lock.ok) {
    return Object.assign(lock, {
      summary,
      nearest: nearestSlots(store, { orgId: input.orgId, customerId: input.customerId, serviceId: service.id, practitionerId: person.id }, start),
    });
  }
  if (input.confirm !== true) {
    return fail("confirm_required", "Show the service, practitioner, date, time, and price. Wait for a yes.", { summary });
  }
  const again = lockBooking(store, {
    orgId: input.orgId,
    practitionerId: person.id,
    customerId: input.customerId,
    startMs: start.getTime(),
    endMs: end.getTime(),
    ignoreBookingId: booking.id,
  });
  if (!again.ok) {
    return Object.assign(again, {
      summary,
      nearest: nearestSlots(store, { orgId: input.orgId, customerId: input.customerId, serviceId: service.id, practitionerId: person.id }, start),
    });
  }
  booking.start = start.toISOString();
  booking.end = end.toISOString();
  booking.practitionerId = person.id;
  booking.price = service.price;
  return { ok: true, booking, summary };
}

function cancelBooking(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const booking = store.bookings.find((row) => row.id === input.bookingId);
  if (!booking || booking.orgId !== input.orgId || booking.customerId !== input.customerId || booking.status !== "booked") {
    return fail("not_your_booking", "That booking is not yours.");
  }
  const service = serviceRow(store, input.orgId, booking.serviceId);
  const person = practitionerRow(store, input.orgId, booking.practitionerId);
  const start = new Date(booking.start);
  const summary = bookingSummary(service, person, start, booking.price);
  if (input.confirm !== true) {
    return fail("confirm_required", "Wait for a yes before cancelling this booking.", { summary });
  }
  const now = input.now ? new Date(input.now) : new Date();
  const hoursUntil = (start.getTime() - now.getTime()) / 36e5;
  const policy = store.bookingPolicy;
  const late = hoursUntil < policy.cancelFreeHours;
  booking.status = "cancelled";
  const knowledge = store.knowledge.find((row) => row.orgId === input.orgId && row.document === policy.document && row.section === policy.section);
  return {
    ok: true,
    bookingId: booking.id,
    status: booking.status,
    feeRate: late ? policy.lateFeeRate : 0,
    document: policy.document,
    section: policy.section,
    policyText: knowledge ? knowledge.text : "",
    summary,
  };
}

function listMyBookings(store, input) {
  const gate = requireCustomer(store, input.orgId, input.customerId);
  if (!gate.ok) return gate;
  const now = Date.now();
  const rows = store.bookings.filter((row) => row.orgId === input.orgId && row.customerId === input.customerId);
  const mapRow = (row) => ({
    id: row.id,
    serviceId: row.serviceId,
    practitionerId: row.practitionerId,
    start: row.start,
    end: row.end,
    price: row.price,
    status: row.status,
    when: Date.parse(row.end) >= now ? "upcoming" : "past",
  });
  return {
    ok: true,
    upcoming: rows.filter((row) => row.status === "booked" && Date.parse(row.end) >= now).map(mapRow),
    past: rows.filter((row) => row.status !== "booked" || Date.parse(row.end) < now).map(mapRow),
  };
}

function argsOf(ctx) {
  return ctx.args || {};
}

function runTool(store, action, ctx) {
  const orgId = ctx.sessionOrgId;
  const customerId = ctx.sessionCustomerId;
  const args = argsOf(ctx);
  const input = Object.assign({}, args, { orgId, customerId });
  if (action === "search_knowledge") return searchKnowledge(store, { orgId, query: args.query || args.text || "" });
  if (action === "search_products") return searchProducts(store, input);
  if (action === "quote_order") return quoteOrder(store, input);
  if (action === "create_order") return createOrder(store, input);
  if (action === "update_order") return updateOrder(store, input);
  if (action === "cancel_order") return cancelOrder(store, input);
  if (action === "get_order_status") return getOrderStatus(store, input);
  if (action === "list_my_orders") return listMyOrders(store, input);
  if (action === "reorder") return reorder(store, input);
  if (action === "list_services") return listServices(store, input);
  if (action === "get_opening_hours") return getOpeningHours(store, input);
  if (action === "find_available_slots") return findAvailableSlots(store, input);
  if (action === "create_booking") return createBooking(store, input);
  if (action === "reschedule_booking") return rescheduleBooking(store, input);
  if (action === "cancel_booking") return cancelBooking(store, input);
  if (action === "list_my_bookings") return listMyBookings(store, input);
  return fail("unknown_tool", "That tool is not on this agent.");
}
function storePaths() {
  const paths = ['/tmp/himali-lotus-chat-state.json'];
  try { if (process.env.N8N_USER_FOLDER) paths.unshift(process.env.N8N_USER_FOLDER + '/himali-lotus-chat-state.json'); } catch (e) {}
  return paths;
}
function readFs() {
  try { return require('fs'); } catch (e) {}
  try { return process.mainModule.require('fs'); } catch (e) {}
  return null;
}
function readFileState() {
  const fs = readFs();
  if (!fs) return null;
  for (const path of storePaths()) {
    try { if (fs.existsSync(path)) return JSON.parse(fs.readFileSync(path, 'utf8')); } catch (e) {}
  }
  return null;
}
function memoryBag() {
  const roots = [];
  try { roots.push(globalThis); } catch (e) {}
  try { roots.push(global); } catch (e) {}
  for (const root of roots) {
    if (root && root.__himaliLotus && root.__himaliLotus.store) return root.__himaliLotus;
  }
  const root = roots[0];
  if (!root) return {};
  if (!root.__himaliLotus) root.__himaliLotus = {};
  return root.__himaliLotus;
}
function loadState() {
  const data = $getWorkflowStaticData('global');
  const mem = memoryBag();
  const picked = chooseState([mem, readFileState(), data], SEED);
  data.store = picked.store;
  data.sessions = picked.sessions;
  data.savedAt = picked.savedAt;
  mem.store = data.store;
  mem.sessions = data.sessions;
  mem.savedAt = data.savedAt;
  return data;
}
function saveState(data) {
  data.savedAt = Date.now();
  const mem = memoryBag();
  mem.store = data.store;
  mem.sessions = data.sessions;
  mem.savedAt = data.savedAt;
  const fs = readFs();
  if (!fs) return;
  const payload = JSON.stringify({ store: data.store, sessions: data.sessions, savedAt: data.savedAt });
  for (const path of storePaths()) {
    try { fs.writeFileSync(path, payload); } catch (e) {}
  }
}
function sessionRow() {
  const row = $('Prepare session').first().json;
  return { orgId: row.orgId, customerId: row.customerId };
}
let raw = '';
try { raw = typeof query === 'undefined' ? '' : query; } catch (e) { raw = ''; }
let args = {};
if (typeof raw === 'string' && raw.trim()) {
  try { args = JSON.parse(raw); } catch (e) { args = { query: raw }; }
} else if (raw && typeof raw === 'object') {
  args = raw;
}
try {
  const who = sessionRow();
  const state = loadState();
  const result = runTool(state.store, action, {
    sessionOrgId: who.orgId,
    sessionCustomerId: who.customerId,
    args: args
  });
  saveState(state);
  return JSON.stringify(result);
} catch (e) {
  return JSON.stringify({ ok: false, code: 'tool_error', message: 'The tool failed.' });
